{
  "story": "Deoxygenated blood enters the right atrium, moves to the right ventricle, gets pumped to the lungs for oxygen, returns to the left atrium, and enters the left ventricle to be pumped out to the entire body.",
  "aha": {
    "stateId": "pump",
    "observation": "Ventricle contraction forces blood through the semilunar valves into the arteries while AV valves snap shut."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "heart-diagram",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "metrics",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Heart Cycle Step",
      "options": [
        "Fill Atria",
        "Atrial Kick",
        "Ventricle Pump",
        "Systemic Flow"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Cardiac Cycle",
        "regions": [
          {
            "id": "ra",
            "label": "Right Atrium",
            "kind": "chamber",
            "values": ["Pressure: Low", "Volume: Filling"]
          },
          {
            "id": "rv",
            "label": "Right Ventricle",
            "kind": "chamber",
            "values": ["Pressure: Low", "Volume: Mid"]
          },
          {
            "id": "la",
            "label": "Left Atrium",
            "kind": "chamber",
            "values": ["Pressure: Low", "Volume: Filling"]
          },
          {
            "id": "lv",
            "label": "Left Ventricle",
            "kind": "chamber",
            "values": ["Pressure: Low", "Volume: Mid"]
          }
        ],
        "states": [
          {
            "id": "fill",
            "label": "Passive Fill",
            "short": "Fill",
            "sentence": "Blood flows passively from veins into both atria and through open valves into ventricles.",
            "why": "Atrioventricular valves open due to higher atrial pressure.",
            "active": ["ra", "la"],
            "calloutRegion": "ra",
            "readouts": [
              {
                "id": "r1",
                "label": "Atrial Pressure",
                "value": "5 mmHg"
              },
              {
                "id": "r2",
                "label": "Ventricle Pressure",
                "value": "2 mmHg"
              }
            ]
          },
          {
            "id": "kick",
            "label": "Atrial Kick",
            "short": "Kick",
            "sentence": "The atria contract to squeeze the remaining blood completely into the ventricles.",
            "why": "Active atrial contraction tops off ventricular volume.",
            "active": ["ra", "la", "rv", "lv"],
            "calloutRegion": "la",
            "readouts": [
              {
                "id": "r1",
                "label": "Atrial Pressure",
                "value": "8 mmHg"
              },
              {
                "id": "r2",
                "label": "Ventricle Pressure",
                "value": "6 mmHg"
              }
            ]
          },
          {
            "id": "pump",
            "label": "Ventricle Pump",
            "short": "Pump",
            "sentence": "Ventricles contract fiercely, forcing blood out through pulmonary and aortic valves.",
            "why": "High ventricular pressure snaps AV valves shut and opens semilunar valves.",
            "active": ["rv", "lv"],
            "calloutRegion": "lv",
            "readouts": [
              {
                "id": "r1",
                "label": "Atrial Pressure",
                "value": "3 mmHg"
              },
              {
                "id": "r2",
                "label": "Ventricle Pressure",
                "value": "120 mmHg"
              }
            ]
          },
          {
            "id": "flow",
            "label": "Systemic Flow",
            "short": "Flow",
            "sentence": "Oxygenated blood travels through the body while deoxygenated blood returns to the heart.",
            "why": "Arterial pressure drives circulation forward.",
            "active": ["ra", "la"],
            "calloutRegion": "rv",
            "readouts": [
              {
                "id": "r1",
                "label": "Atrial Pressure",
                "value": "4 mmHg"
              },
              {
                "id": "r2",
                "label": "Ventricle Pressure",
                "value": "10 mmHg"
              }
            ]
          }
        ]
      }
    ]
  }
}
